def lowestCommonAncestorBST(root_val: int, p: int, q: int) -> int:
    # In a BST rooted at root_val: if both < root_val, LCA is in left; if both > root_val, right; else root_val
    low, high = min(p, q), max(p, q)
    if low <= root_val <= high:
        return root_val
    elif high < root_val:
        return low
    else:
        return high

